#!/usr/bin/env python3
"""Create audiobook from Paul Graham essays."""

import os
import re
import subprocess
import requests
from openai import OpenAI
from gtts import gTTS
import time

# --- Fetching & Cleaning ---

def fetch_article_content(url):
    """Fetch article content using curl for reliability."""
    print(f"Fetching {url}...")
    try:
        # Use curl to get raw HTML - mimicking a browser slightly to avoid blocking
        result = subprocess.run(
            ["curl", "-s", "-L", "-A", "Mozilla/5.0", url],
            capture_output=True,
            text=True
        )
        html = result.stdout
        if not html:
            print(f"Error: Empty response from {url}")
            return ""

        # Specific extraction for paulgraham.com to get better text
        # His essays usually start after a specific table structure or font tag, but are simple HTML.
        # Let's try to grab the body content.

        # Remove script and style
        text = re.sub(r'<script[^>]*>.*?</script>', '', html, flags=re.DOTALL | re.IGNORECASE)
        text = re.sub(r'<style[^>]*>.*?</style>', '', text, flags=re.DOTALL | re.IGNORECASE)

        # Quick and dirty extraction of the main text block
        # PG essays are often in <font face="verdana"> or similar. 
        # But generic tag stripping is usually robust enough for his site if we remove head/nav.

        text = re.sub(r'<[^>]+>', ' ', text)
        text = re.sub(r'\s+', ' ', text).strip()

        # Heuristic: Remove the footer/header junk if possible. 
        # PG site usually has "Paul Graham" at top and "©" at bottom. 
        # We can just keep it all, TTS handles it fine usually, or the user can skip.

        return text
    except Exception as e:
        print(f"Error fetching {url}: {e}")
        return ""

def clean_text_for_tts(text):
    """Clean text for better TTS output."""
    # Remove URLs
    text = re.sub(r'http[s]?://\S+', ' ', text)
    # Remove footnote markers like [1], [2]
    text = re.sub(r'\[\d+\]', ' ', text)
    # Normalize whitespace
    text = re.sub(r'\s+', ' ', text)
    return text.strip()

def chunk_text(text, max_chars=4000):
    """Split text into chunks at sentence boundaries."""
    # Split by sentence endings.
    sentences = re.split(r'(?<=[.!?])\s+', text)
    chunks = []
    current_chunk = ""

    for sentence in sentences:
        if len(current_chunk) + len(sentence) < max_chars:
            current_chunk += sentence + " "
        else:
            if current_chunk:
                chunks.append(current_chunk.strip())
            current_chunk = sentence + " "

    if current_chunk:
        chunks.append(current_chunk.strip())

    return chunks

# --- TTS Providers ---

def create_with_elevenlabs(text, output_path):
    """Generate audiobook using ElevenLabs API."""
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    if not api_key:
        return False

    print("Using ElevenLabs TTS...")
    voice_id = "21m00Tcm4TlvDq8ikWAM"  # Rachel

    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_el_{i:03d}.mp3"
        try:
            response = requests.post(
                f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
                headers={
                    "xi-api-key": api_key,
                    "Content-Type": "application/json"
                },
                json={
                    "text": chunk,
                    "model_id": "eleven_turbo_v2_5",
                    "voice_settings": {"stability": 0.5, "similarity_boost": 0.75}
                }
            )

            if response.status_code == 200:
                with open(chunk_file, "wb") as f:
                    f.write(response.content)
                audio_files.append(chunk_file)
            else:
                print(f"ElevenLabs Error: {response.status_code} - {response.text}")
                return False
        except Exception as e:
            print(f"ElevenLabs Exception: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_with_openai(text, output_path):
    """Generate audiobook using OpenAI TTS API."""
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        return False

    print("Using OpenAI TTS...")
    client = OpenAI(api_key=api_key)

    chunks = chunk_text(text, max_chars=4000)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_oa_{i:03d}.mp3"
        try:
            response = client.audio.speech.create(
                model="tts-1",
                voice="onyx",
                input=chunk
            )
            response.stream_to_file(chunk_file)
            audio_files.append(chunk_file)
        except Exception as e:
            print(f"OpenAI Error: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_with_gtts(text, output_path):
    """Generate audiobook using gTTS (free)."""
    print("Using gTTS (fallback)...")
    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_gt_{i:03d}.mp3"
        try:
            tts = gTTS(text=chunk, lang='en', slow=False)
            tts.save(chunk_file)
            audio_files.append(chunk_file)
        except Exception as e:
            print(f"gTTS Error: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

# --- Helpers ---

def concatenate_audio(audio_files, output_path):
    """Concatenate multiple audio files using ffmpeg."""
    if not audio_files:
        return False

    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")

    try:
        subprocess.run([
            "ffmpeg", "-y", "-f", "concat", "-safe", "0",
            "-i", list_file, "-c", "copy", output_path
        ], capture_output=True, check=True)
    except subprocess.CalledProcessError as e:
        print(f"FFmpeg Error: {e}")
        return False
    finally:
        # Cleanup
        if os.path.exists(list_file):
            os.unlink(list_file)
        for f in audio_files:
            if os.path.exists(f):
                os.unlink(f)

    return True

def create_audiobook(text, output_path):
    # Priority: ElevenLabs -> OpenAI -> gTTS
    if os.environ.get("ELEVENLABS_API_KEY"):
        if create_with_elevenlabs(text, output_path):
            return True
        print("ElevenLabs failed, trying OpenAI...")

    if os.environ.get("OPENAI_API_KEY"):
        if create_with_openai(text, output_path):
            return True
        print("OpenAI failed, trying gTTS...")

    return create_with_gtts(text, output_path)

def main():
    urls = [
        "https://paulgraham.com/ds.html",
        "https://paulgraham.com/foundermode.html"
    ]

    full_text = ""
    for url in urls:
        raw_text = fetch_article_content(url)
        if not raw_text:
            print(f"Skipping {url} due to fetch error.")
            continue

        clean = clean_text_for_tts(raw_text)
        print(f"Fetched {len(clean)} chars from {url}")

        # Add a title announcement
        title = "Essay: " + url.split('/')[-1].replace('.html', '').replace('ds', 'Do Things That Don\'t Scale').replace('foundermode', 'Founder Mode').replace('_', ' ')
        full_text += f"{title}.\n\n{clean}\n\n"

    if not full_text.strip():
        print("No text fetched.")
        return

    output_file = "/root/audiobook.mp3"
    print(f"Generating audiobook to {output_file}...")
    if create_audiobook(full_text, output_file):
        print(f"Success! Saved to {output_file}")
    else:
        print("Failed to create audiobook.")

if __name__ == "__main__":
    main()

